import styled from 'styled-components'

interface CarrinhoContainerProps {
  isOpen: boolean // Definir o tipo da propriedade `isOpen`
}

export const CarrinhoContainer = styled.aside<CarrinhoContainerProps>`
  width: 300px;
  height: 100vh;
  background: #fff;
  position: fixed;
  top: 0;
  right: ${(props) =>
    props.isOpen
      ? '0'
      : '-300px'}; /* A posição é ajustada com base no estado */
  box-shadow: -2px 0 5px rgba(0, 0, 0, 0.1);
  padding: 20px;
  overflow-y: auto;
  transition: right 0.3s ease-in-out; /* Animação suave para abrir/fechar */
  z-index: 99;
`

export const CarrinhoHeader = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
`

export const CarrinhoLista = styled.ul`
  list-style: none;
  padding: 0;
`

export const CarrinhoItem = styled.li`
  display: flex;
  align-items: center;
  margin-bottom: 15px;
  img {
    width: 50px;
    height: 50px;
    object-fit: cover;
    margin-right: 10px;
  }
  div {
    flex: 1;
  }
  button {
    background: #ff6347;
    color: #fff;
    border: none;
    padding: 5px 10px;
    cursor: pointer;
  }
`

export const CarrinhoTotal = styled.div`
  margin-top: 20px;
  font-weight: bold;
`

export const CarrinhoButton = styled.button`
  width: 100%;
  padding: 10px;
  background: #32cd32;
  color: #fff;
  border: none;
  cursor: pointer;
  margin-top: 20px;
`
